window.TANI_DATA={overview:{title:"The Tani Languages of Arunachal Pradesh",family:"Sino-Tibetan (Trans-Himalayan) ➔ Tani Branch",speakers:"600,000+",districtsCovered:11,commonAncestor:"Abotani (Legendary Progenitor of Tani People)",description:"The Tani languages constitute a distinct, closely related group of Sino-Tibetan languages spoken across central Arunachal Pradesh and adjacent areas of Assam. Rather than a single uniform language, the region exhibits vibrant linguistic diversity bonded by shared ancestral genealogy, Abotani folklore, and agglutinative grammatical structures."},genealogy:{root:"Proto-Sino-Tibetan",branch:"Trans-Himalayan / Tibeto-Burman",subgroup:"Tani Sub-Family",characteristics:[{title:"Agglutinative Morphology",desc:"Verbs combine multiple suffixes to convey direction, aspect, mood, and causative action in single compound words."},{title:"Unrounded Central Vowels",desc:"Distinctive vowels such as /ɨ/ and /ɯ/ (often written as 'ii', 'ui', or 'ï' in Tani orthography)."},{title:"Directional Verbal Markers",desc:"Verbs explicitly encode spatial directions (e.g., movement upward, downward, upstream, or downstream)."},{title:"Numeral Classifier System",desc:"Nouns require specific classifiers when counted based on shape, animacy, or physical texture."}],divisions:[{name:"Western Tani",languages:["Nyishi","Apatani","Tagin","Bangni","Damu","Hill Miri (Sanga)"],features:"Stronger preservation of initial voiced stops, specific glottal stop phenomena in Apatani."},{name:"Eastern Tani",languages:["Adi (Padam, Minyong, Pasium, Shimong, Bokar, Bori)","Mising"],features:"Distinctive tonal pitch accents, shared lexical innovations between Siang valley and Brahmaputra plains."},{name:"Pre-Tani / Central",languages:["Galo"],features:"Transitional features between Western and Eastern Tani, famous for strict patrilineal oral genealogy (Agom)."}]},languages:[{id:"nyishi",name:"Nyishi",nativeName:"𑲂𑲍𑲉 / Nyi-shi",ipa:"/ɲiɕi/",speakers:"approx. 300,000",subGroup:"Western Tani",primaryDistricts:["Papum Pare","East Kameng","Lower Subansiri","Kurung Kumey","Kra Daadi","Kamle"],color:"#e11d48",writingSystem:"Standardized Nyishi Latin Orthography (NES approved) & Tani Lipi script",description:"Nyishi is the most widely spoken Tani language in Arunachal Pradesh. It features rich oral poetry, proverb collections (Durney), and complex verb prefixes denoting temporal distance.",varieties:["Yano","Nyisu","Akang","Sanga (Hill Miri)"],culturalKey:"Nyokum Yullo festival, Hornbill Bopia cap, Solu/Padam traditions"},{id:"adi",name:"Adi",nativeName:"𑱵𑱴 / Adi",ipa:"/adi/",speakers:"approx. 140,000",subGroup:"Eastern Tani",primaryDistricts:["East Siang","Upper Siang","Siang","Shi Yomi"],color:"#059669",writingSystem:"Adi Latin Orthography (Adi Agom Kébang) & Tani Lipi script",description:"Adi (formerly known historically as Abor) encompasses a dialect cluster spoken along the mighty Siang river valley. Known for its classical oral chants (Abe) recited during Solung.",varieties:["Padam","Minyong","Shimong","Pasium","Bokar","Bori","Karko"],culturalKey:"Solung Festival, Ponung Dance, Musup / Dere community hall"},{id:"apatani",name:"Apatani",nativeName:"𑲄𑲎𑲉 / Tanii",ipa:"/taːniː/",speakers:"approx. 45,000",subGroup:"Western Tani",primaryDistricts:["Lower Subansiri (Ziro Valley)"],color:"#d97706",writingSystem:"Tanii Latin Orthography & Tani Lipi script",description:"Spoken exclusively in the UNESCO-tentative Ziro Valley, Apatani features unique phonological traits such as final glottal stops, distinctive tone shifts, and nasalized vowels.",varieties:["Ziro Central","Dulo","Hang"],culturalKey:"Dree & Myoko festivals, Paddy-cum-fish cultivation, Yaping Hullo (nose plugs)"},{id:"galo",name:"Galo",nativeName:"𑲅𑲉𑲍 / Galo",ipa:"/ɡalo/",speakers:"approx. 130,000",subGroup:"Central Tani",primaryDistricts:["West Siang","Leparada","Lower Siang"],color:"#2563eb",writingSystem:"Galo Latin Orthography (GWS approved) & Tani Lipi script",description:"Galo possesses a remarkable patrilineal naming convention where every person's first name begins with the last syllable of their father's name, tracing ancestry back to Abotani.",varieties:["Lare","Pugo","Karki","Ramo"],culturalKey:"Mopin Festival, Popir dance, White rice powder blessings"},{id:"tagin",name:"Tagin",nativeName:"Tagin / Na",ipa:"/taɡin/",speakers:"approx. 60,000",subGroup:"Western Tani",primaryDistricts:["Upper Subansiri (Daporijo)","Shi Yomi"],color:"#7c3aed",writingSystem:"Tagin Latin Script & Tani Lipi script",description:"Spoken in the rugged upper reaches of Subansiri river, Tagin bridges Western Tani with northern high-altitude varieties. Maintains strong shamanic Nyibu ritual traditions.",varieties:["Daporijo","Dumporijo","Mara","Na"],culturalKey:"Si-Donyi Festival, Sun-Earth worship, Sacred ritual pole (Sii)"},{id:"mising",name:"Mising",nativeName:"𑱷𑱲𑱰 / Mising",ipa:"/miɕiŋ/",speakers:"approx. 650,000 (Arunachal & Assam)",subGroup:"Eastern Tani",primaryDistricts:["East Siang","Namsai","Assam Border Plains"],color:"#0891b2",writingSystem:"Mising Agom Kébang Latin Orthography",description:"Mising is closely related to Adi and is spoken along the riverine plains where the Siang meets the Brahmaputra. Has a rich written literary tradition in Latin script.",varieties:["Oyan","Pagro","Dellu","Dambuk"],culturalKey:"Ali-Aye-Ligang spring festival, Gumrag dance, Riverine stilt houses"}],districts:[{id:"papum-pare",name:"Papum Pare",cap:"Itanagar",lang:"nyishi",desc:"Capital district & major Nyishi cultural hub."},{id:"lower-subansiri",name:"Lower Subansiri",cap:"Ziro",lang:"apatani",desc:"Home of Ziro Valley and Apatani language culture."},{id:"east-kameng",name:"East Kameng",cap:"Seppa",lang:"nyishi",desc:"Westernmost stronghold of Nyishi varieties."},{id:"kurung-kumey",name:"Kurung Kumey",cap:"Koloriang",lang:"nyishi",desc:"High mountain valleys of Nyishi speakers."},{id:"kra-daadi",name:"Kra Daadi",cap:"Jamin",lang:"nyishi",desc:"Heartland of traditional Nyishi folklore."},{id:"east-siang",name:"East Siang",cap:"Pasighat",lang:"adi",desc:"Cultural capital of Adi and Mising speakers."},{id:"upper-siang",name:"Upper Siang",cap:"Yingkiong",lang:"adi",desc:"Upstream Siang river region of Padam & Minyong Adi."},{id:"siang",name:"Siang",cap:"Boleng",lang:"adi",desc:"Central Adi heartland surrounded by lush hills."},{id:"west-siang",name:"West Siang",cap:"Aalo",lang:"galo",desc:"Cultural epicentre of Galo language and Mopin festival."},{id:"leparada",name:"Leparada",cap:"Basar",lang:"galo",desc:"Scenic Galo valleys known for agro-tourism & caves."},{id:"upper-subansiri",name:"Upper Subansiri",cap:"Daporijo",lang:"tagin",desc:"Subansiri canyon lands of the Tagin language."}],greetings:[{langId:"nyishi",langName:"Nyishi",category:"Welcome / Greeting",native:"𑲂𑲍𑲉 - Kulum-jo!",latin:"Kulum-jo / Niku-a",ipa:"[kulum dʑo]",meaning:"Respectful Greetings / Welcome",phoneticSynth:"Koo-loom joh",note:"Used when welcoming guests into a traditional Nyishi house (Namlo)."},{langId:"nyishi",langName:"Nyishi",category:"How are you?",native:"Noh ikam-da?",latin:"Noh ikam-da?",ipa:"[no ikam da]",meaning:"How are you doing?",phoneticSynth:"Noh ee-kahm dah",note:"Common warm query among family and friends."},{langId:"nyishi",langName:"Nyishi",category:"Thank You",native:"Kapa-bo / Kulum-da",latin:"Kapa-bo / Kulum-da",ipa:"[kapa bo]",meaning:"Thank you / Gratitude expressed",phoneticSynth:"Kah-pah boh",note:"Used to show appreciation for hospitality or help."},{langId:"nyishi",langName:"Nyishi",category:"Farewell",native:"Hai-ba-jo / Jol-la-ju",latin:"Hai-ba-jo",ipa:"[hai ba dʑo]",meaning:"Goodbye / Go well",phoneticSynth:"High bah joh",note:"Said when departing; wishes safe journey."},{langId:"adi",langName:"Adi",category:"Welcome / Greeting",native:"𑱵𑱴 - Kuma-laju!",latin:"Kuma-laju / Mingkeng Kuma",ipa:"[kuma ladʑu]",meaning:"Warm Welcome / Greetings",phoneticSynth:"Koo-mah lah-joo",note:"Standard greeting in Pasighat and Siang valley."},{langId:"adi",langName:"Adi",category:"How are you?",native:"Nokke aiyeng-ai?",latin:"Nokke aiyeng-ai?",ipa:"[nokke aijeŋ ai]",meaning:"Are you well?",phoneticSynth:"Nok-keh eye-yeng eye",note:"Literal: 'Is your well-being intact?'"},{langId:"adi",langName:"Adi",category:"Thank You",native:"Kapa-kai / Nol-lo kapa-kai",latin:"Kapa-kai",ipa:"[kapa kai]",meaning:"Thank you very much",phoneticSynth:"Kah-pah kye",note:"Commonly spoken in Solung festive gatherings."},{langId:"adi",langName:"Adi",category:"Farewell",native:"Gi-joo-ka!",latin:"Gi-joo-ka",ipa:"[ɡi dʑoː ka]",meaning:"Please go safely",phoneticSynth:"Ghee joo kah",note:"Formal departure wish."},{langId:"apatani",langName:"Apatani",category:"Welcome / Greeting",native:"𑲄𑲎𑲉 - Sani-ba!",latin:"Sani-ba / Kulum-jo",ipa:"[sani ba]",meaning:"Greetings / Hello",phoneticSynth:"Sah-nee bah",note:"Traditional Ziro valley welcome greeting."},{langId:"apatani",langName:"Apatani",category:"How are you?",native:"Noni tani-si kago-ha?",latin:"Noni tani-si kago-ha?",ipa:"[noni tani si kaɡo ha]",meaning:"Are you fine in health?",phoneticSynth:"No-nee tah-nee see kah-go hah",note:"Uses characteristic Apatani pitch contour."},{langId:"apatani",langName:"Apatani",category:"Thank You",native:"Hulyo-ka / Kapa-bo",latin:"Hulyo-ka",ipa:"[huljo ka]",meaning:"Thank you kindly",phoneticSynth:"Hool-yoh kah",note:"Used during Myoko community feast exchanges."},{langId:"apatani",langName:"Apatani",category:"Farewell",native:"Pyii-jo / Pii-la-ju",latin:"Pyii-jo",ipa:"[pjiː dʑo]",meaning:"Farewell / Until we meet",phoneticSynth:"Pyee joh",note:"Features unrounded vowel prolongation."},{langId:"galo",langName:"Galo",category:"Welcome / Greeting",native:"𑲅𑲉𑲍 - Yilo-kuma!",latin:"Yilo-kuma / Kulum-na",ipa:"[jilo kuma]",meaning:"Blessed Greetings / Welcome",phoneticSynth:"Yee-loh koo-mah",note:"Spoken during Mopin rice-powder blessing rituals."},{langId:"galo",langName:"Galo",category:"How are you?",native:"Nom-e aii-da-ge?",latin:"Nom-e aii-da-ge?",ipa:"[nom e aiː da ɡe]",meaning:"How are you doing today?",phoneticSynth:"Nom-eh eye-dah-geh",note:"Central Galo conversational opening."},{langId:"galo",langName:"Galo",category:"Thank You",native:"Kapar-bo / Kapa-ka-mulu",latin:"Kapar-bo",ipa:"[kapar bo]",meaning:"Many thanks",phoneticSynth:"Kah-par boh",note:"Used to thank village elders and hosts."},{langId:"galo",langName:"Galo",category:"Farewell",native:"In-la-ju / Aan-la-ju",latin:"In-la-ju",ipa:"[in la dʑu]",meaning:"Let us depart / Goodbye",phoneticSynth:"In lah joo",note:"'In-la-ju' means 'let us go' (departing visitor)."},{langId:"tagin",langName:"Tagin",category:"Welcome / Greeting",native:"Ayi-da!",latin:"Ayi-da / Kulum-jo",ipa:"[aji da]",meaning:"Greetings / Peace be with you",phoneticSynth:"Ah-yee dah",note:"Tagin valley greeting during Si-Donyi worship."},{langId:"tagin",langName:"Tagin",category:"How are you?",native:"Noh ayi-da-ge?",latin:"Noh ayi-da-ge?",ipa:"[no aji da ɡe]",meaning:"Are you doing well?",phoneticSynth:"Noh ah-yee dah geh",note:"Standard Upper Subansiri greeting."},{langId:"tagin",langName:"Tagin",category:"Thank You",native:"Kapa-bo",latin:"Kapa-bo",ipa:"[kapa bo]",meaning:"Thank you",phoneticSynth:"Kah-pah boh",note:"Appreciation phrase."},{langId:"tagin",langName:"Tagin",category:"Farewell",native:"Gi-la-ju",latin:"Gi-la-ju",ipa:"[ɡi la dʑu]",meaning:"Goodbye / Go peacefully",phoneticSynth:"Ghee lah joo",note:"Farewell blessing."},{langId:"mising",langName:"Mising",category:"Welcome / Greeting",native:"𑱷𑱲𑱰 - Kuma-bo!",latin:"Kuma-bo / Ali-Aye",ipa:"[kuma bo]",meaning:"Heartfelt Welcome",phoneticSynth:"Koo-mah boh",note:"Proclaimed at Ali-Aye-Ligang spring festival."},{langId:"mising",langName:"Mising",category:"How are you?",native:"Nokke aying-a?",latin:"Nokke aying-a?",ipa:"[nokke ajiŋ a]",meaning:"Are you well?",phoneticSynth:"Nok-keh eye-ing ah",note:"Riverine plain dialect expression."},{langId:"mising",langName:"Mising",category:"Thank You",native:"Karpang-kuma / Kapa-kai",latin:"Karpang-kuma",ipa:"[karpaŋ kuma]",meaning:"Sincere thanks",phoneticSynth:"Kar-pang koo-mah",note:"Literary Mising gratitude expression."},{langId:"mising",langName:"Mising",category:"Farewell",native:"Okum-lo-gi-ku-ju",latin:"Okum-lo-gi-ku-ju",ipa:"[okum lo ɡi ku dʑu]",meaning:"Let us return home safely",phoneticSynth:"Oh-koom loh ghee koo joo",note:"Traditional homebound farewell."}],vocabularyMatrix:[{concept:"Water",protoTani:"*si",nyishi:"Esi / Si",adi:"Asi",apatani:"Yasi / Si",galo:"Isi",tagin:"Isi / Si",mising:"Asi",ipa:"/si / asi / isi/",etymology:"Derived from Proto-Tani root *si meaning liquid/water element."},{concept:"Fire",protoTani:"*emi",nyishi:"Umyi / Emi",adi:"Emi",apatani:"Emyi",galo:"Emi",tagin:"Emi",mising:"Eme",ipa:"/emi / emje / eme/",etymology:"Cognate across all Tani branches with minimal phonetic variation."},{concept:"Sun",protoTani:"*donyi",nyishi:"Donyi",adi:"Donyi",apatani:"Donyi",galo:"Donyi",tagin:"Donyi",mising:"Donyi",ipa:"/doɲi/",etymology:"Sacred root *donyi (Sun deity/force), central to Tani cosmology (Si-Donyi / Donyi-Polo)."},{concept:"Moon",protoTani:"*polo",nyishi:"Polo",adi:"Polo",apatani:"Polo",galo:"Polo",tagin:"Polo",mising:"Polo",ipa:"/polo/",etymology:"Paired with Donyi to form Donyi-Polo (Sun-Moon spiritual tradition)."},{concept:"House",protoTani:"*eku / *nam",nyishi:"Namlo",adi:"Ekum",apatani:"Iki / Nam",galo:"Nam",tagin:"Nam / Ekum",mising:"Okum",ipa:"/namlo / ekum / okum/",etymology:"Split between two ancient roots: *nam (structure/dwelling) and *ekum (shelter)."},{concept:"Man / Person",protoTani:"*tani / *nyi",nyishi:"Nyi / Tani",adi:"Ami / Tani",apatani:"Tanii",galo:"Tani / Nyibo",tagin:"Tani / Nyi",mising:"Ami / Tani",ipa:"/tani / ɲi / ami/",etymology:"Root *tani is the self-designation for human being, giving name to the entire Tani language group."},{concept:"Woman",protoTani:"*nyime / *milo",nyishi:"Nyime",adi:"Mime",apatani:"Nyime",galo:"Nyime",tagin:"Nyime",mising:"Yame / Mime",ipa:"/ɲime / mime/",etymology:"Proto-Tani female prefix *nyi- / *mi- combined with feminine nominal marker."},{concept:"Tree / Wood",protoTani:"*sane / *esing",nyishi:"Sangne",adi:"Esing",apatani:"Sani",galo:"Esing",tagin:"Esing / Sange",mising:"Esing",ipa:"/saŋne / esiŋ / sani/",etymology:"Reconstructed *sing / *sane denoting flora and timber."},{concept:"Eye",protoTani:"*amuk / *nyi",nyishi:"Niking",adi:"Amik",apatani:"Yani",galo:"Amik",tagin:"Amik / Niking",mising:"Amik",ipa:"/amik / nikiŋ/",etymology:"Eastern Tani preserves *amik while Western Tani shows compound form with *nyi (see)."},{concept:"Heart / Mind",protoTani:"*apo / *aying",nyishi:"Ahing",adi:"Aying",apatani:"Ahu",galo:"Aying",tagin:"Aying",mising:"Aying",ipa:"/ahiŋ / ajiŋ / ahu/",etymology:"Root *aying signifies both physical heart and emotional core in Tani philosophy."}],writingSystems:{traditional:{title:"Oral Chants & Ancestral Genealogy",desc:"For centuries, Tani heritage was preserved through oral literature known as Nyibu Agom (shamanic chants), Abe (formal public speeches), and Baya (epic ballads). Genealogies were memorized through father-to-son naming chains back to Abotani."},modernLatin:{title:"Standardized Latin Orthographies",desc:"Today, Tani languages use adapted Latin scripts with specific diacritics for central vowels (/ɨ/ written as 'ii' or 'ï', /ɯ/ as 'ui' or 'e'). Organizations like Nyishi Elite Society (NES), Adi Agom Kébang (AAK), and Galo Welfare Society (GWS) have standardized text books and literature."},taniLipi:{title:"Tani Lipi Script (Indigenous Innovation)",desc:"Invented by scholar Tony Koyu in the early 2000s, Tani Lipi is a dedicated indigenous script engineered specifically to represent the phonetic nuances of Tani languages—including glottal stops, central unrounded vowels, and pitch accent tones—without relying on Latin diacritics."}},culturalHeritage:[{title:"Abotani Genealogy & Shamanic Chants",category:"Mythology & Oral Epics",icon:"📜",content:"All Tani communities trace their lineage to Abotani, the legendary first human ancestor. Priests known as Nyibu (Nyishi/Tagin) or Miri (Adi/Mising) recite hours of rhythmic oral epics without written texts during sacred rituals."},{title:"Nyokum Yullo (Nyishi)",category:"Harvest & Harmony Festival",icon:"🌾",content:"Celebrated annually in February, Nyokum Yullo invites Goddess Nyokum for agricultural prosperity, communal unity, peace, and protection against natural disasters."},{title:"Solung & Aran (Adi)",category:"Socio-Religious Festival",icon:"🌽",content:"Solung is the chief festival of the Adi people celebrated in September. Features the epic Ponung dance performed by women led by the Miri singer holding a sacred sword (Yoksha)."},{title:"Dree & Myoko (Apatani)",category:"Agricultural & Friendship Festival",icon:"🌿",content:"Dree (July) seeks protection for crops against pests, while Myoko (March) celebrates inter-village brotherhood with traditional flag hoisting and sacred shamanic rites."},{title:"Mopin & Popir Dance (Galo)",category:"Prosperity Festival",icon:"✨",content:"Mopin in April is celebrated to drive away evil spirits and bring wealth. Community members smear sacred white rice powder (Ette) on each other's faces while performing the elegant Popir dance."},{title:"Si-Donyi (Tagin)",category:"Cosmic Worship",icon:"☀️",content:"Celebrated in January, Si-Donyi honors 'Si' (Earth) and 'Donyi' (Sun) as supreme creators. Priests wear ceremonial headgear (Bopia-Donyi) and perform sacred animal blessings."},{title:"Ali-Aye-Ligang (Mising)",category:"Spring Seed Sowing",icon:"🌱",content:"Marks the beginning of the paddy sowing season in February ('Ali' = seed, 'Aye' = fruit, 'Ligang' = sowing). Celebrated with the vibrant Gumrag dance and traditional festive feast (Purang)."},{title:"Attire & Hornbill Bopia Cap",category:"Material Culture & Weaving",icon:"🪶",content:"Distinctive headgear includes the Nyishi Bopia woven from cane and traditionally adorned with a hornbill beak motif. Women across all Tani groups weave intricate geometric handloom skirts known as Gale."}],quizQuestions:[{question:"Who is revered as the common ancestral progenitor across all Tani tribes?",options:["Abotani","Mahatma Gandhi","King Naraka","Guru Padmasambhava"],correct:0,explanation:"Abotani is the legendary ancestral figure to whom all Tani communities (Nyishi, Adi, Apatani, Galo, Tagin, Mising) trace their genealogy."},{question:"What is the common Proto-Tani root word for 'Water'?",options:["*si","*donyi","*polo","*nam"],correct:0,explanation:"Proto-Tani root *si forms modern words like Esi (Nyishi), Asi (Adi/Mising), Yasi (Apatani), and Isi (Galo/Tagin)."},{question:"Which Tani language is spoken predominantly in the UNESCO-tentative Ziro Valley?",options:["Apatani","Adi","Mising","Galo"],correct:0,explanation:"Apatani (Tanii) is spoken in the Ziro Valley of Lower Subansiri district."},{question:"What is 'Tani Lipi'?",options:["An indigenous script created by Tony Koyu for Tani languages","A traditional bamboo dish","A river flowing through Pasighat","A type of hornbill bird"],correct:0,explanation:"Tani Lipi is a dedicated indigenous script developed by scholar Tony Koyu to accurately write Tani languages."},{question:"During which festival do Galo people smear sacred white rice powder (Ette) on each other?",options:["Mopin","Nyokum Yullo","Solung","Dree"],correct:0,explanation:"Mopin is the principal festival of the Galo people, famous for rice powder smearings and the Popir dance."}]};